"""Built-in copy of SMPELOAD.jcl, used only if the .jcl file is not found next to the app."""
TEXT = "//SMPELOAD JOB (ACCT),'SMPE LOAD PRACTICE JCL',CLASS=A,MSGCLASS=X,\n//             NOTIFY=&SYSUID,REGION=0M\n//* LOADS ALL PRACTICE MEMBERS INTO SMPE.PRAC.JCL (SUBMIT ONCE)\n//ALLOC    EXEC PGM=IEFBR14\n//JCL      DD DSN=SMPE.PRAC.JCL,DISP=(NEW,CATLG),UNIT=SYSALLDA,\n//            SPACE=(CYL,(2,1,30)),\n//            DCB=(DSORG=PO,RECFM=FB,LRECL=80,BLKSIZE=27920)\n//LOAD     EXEC PGM=IEBUPDTE,PARM=NEW\n//SYSPRINT DD SYSOUT=*\n//SYSUT2   DD DSN=SMPE.PRAC.JCL,DISP=OLD\n//SYSIN    DD DATA,DLM=##\n./ ADD NAME=SMPEPRC\n//SMPEPRC  PROC\n//* CATALOGED PROC USED BY ALL GIMSMP PRACTICE JOBS\n//SMPE     EXEC PGM=GIMSMP,PARM='DATE=U',REGION=0M\n//SMPCSI   DD DISP=SHR,DSN=SMPE.PRAC.GLOBAL.CSI\n//SMPOUT   DD SYSOUT=*\n//SMPRPT   DD SYSOUT=*\n//SMPLIST  DD SYSOUT=*\n//SMPSNAP  DD SYSOUT=*\n//SYSPRINT DD SYSOUT=*\n//SMPHOLD  DD DUMMY\n//SYSUT1   DD UNIT=SYSALLDA,SPACE=(CYL,(5,2))\n//SYSUT2   DD UNIT=SYSALLDA,SPACE=(CYL,(5,2))\n//SYSUT3   DD UNIT=SYSALLDA,SPACE=(CYL,(5,2))\n//SYSUT4   DD UNIT=SYSALLDA,SPACE=(CYL,(5,2))\n//SMPWRK1  DD UNIT=SYSALLDA,SPACE=(CYL,(5,2,50)),\n//            DCB=(RECFM=FB,LRECL=80,BLKSIZE=3120)\n//SMPWRK2  DD UNIT=SYSALLDA,SPACE=(CYL,(5,2,50)),\n//            DCB=(RECFM=FB,LRECL=80,BLKSIZE=3120)\n//SMPWRK3  DD UNIT=SYSALLDA,SPACE=(CYL,(5,2,50)),\n//            DCB=(RECFM=FB,LRECL=80,BLKSIZE=3120)\n//SMPWRK4  DD UNIT=SYSALLDA,SPACE=(CYL,(5,2,50)),\n//            DCB=(RECFM=FB,LRECL=80,BLKSIZE=3120)\n//SMPWRK6  DD UNIT=SYSALLDA,SPACE=(CYL,(5,2,50)),\n//            DCB=(RECFM=FB,LRECL=80,BLKSIZE=3120)\n//         PEND\n./ ADD NAME=J01ALLOC\n//J01ALLOC JOB (ACCT),'SMPE ALLOCATE LIBS',CLASS=A,MSGCLASS=X,\n//             NOTIFY=&SYSUID,REGION=0M\n//* CHANGE VOL TO A VOLUME WITH 100+ FREE CYLINDERS\n//         SET VOL=USER00\n//ALLOC    EXEC PGM=IEFBR14\n//SMPPTS   DD DSN=SMPE.PRAC.SMPPTS,DISP=(NEW,CATLG),UNIT=SYSALLDA,\n//            VOL=SER=&VOL,SPACE=(CYL,(5,2,50)),\n//            DCB=(DSORG=PO,RECFM=FB,LRECL=80,BLKSIZE=27920)\n//SMPSCDS  DD DSN=SMPE.PRAC.SMPSCDS,DISP=(NEW,CATLG),UNIT=SYSALLDA,\n//            VOL=SER=&VOL,SPACE=(CYL,(5,2,50)),\n//            DCB=(DSORG=PO,RECFM=FB,LRECL=80,BLKSIZE=27920)\n//SMPMTS   DD DSN=SMPE.PRAC.SMPMTS,DISP=(NEW,CATLG),UNIT=SYSALLDA,\n//            VOL=SER=&VOL,SPACE=(CYL,(5,2,50)),\n//            DCB=(DSORG=PO,RECFM=FB,LRECL=80,BLKSIZE=27920)\n//SMPSTS   DD DSN=SMPE.PRAC.SMPSTS,DISP=(NEW,CATLG),UNIT=SYSALLDA,\n//            VOL=SER=&VOL,SPACE=(CYL,(5,2,50)),\n//            DCB=(DSORG=PO,RECFM=FB,LRECL=80,BLKSIZE=27920)\n//SDUMMYL  DD DSN=SMPE.PRAC.SDUMMYL,DISP=(NEW,CATLG),UNIT=SYSALLDA,\n//            VOL=SER=&VOL,SPACE=(CYL,(5,2,50)),\n//            DCB=(DSORG=PO,RECFM=FB,LRECL=80,BLKSIZE=27920)\n//ADUMMYL  DD DSN=SMPE.PRAC.ADUMMYL,DISP=(NEW,CATLG),UNIT=SYSALLDA,\n//            VOL=SER=&VOL,SPACE=(CYL,(5,2,50)),\n//            DCB=(DSORG=PO,RECFM=FB,LRECL=80,BLKSIZE=27920)\n//SMPLOG   DD DSN=SMPE.PRAC.SMPLOG,DISP=(NEW,CATLG),UNIT=SYSALLDA,\n//            VOL=SER=&VOL,SPACE=(CYL,(5,2)),\n//            DCB=(DSORG=PS,RECFM=VB,LRECL=260,BLKSIZE=27998)\n//SMPLOGA  DD DSN=SMPE.PRAC.SMPLOGA,DISP=(NEW,CATLG),UNIT=SYSALLDA,\n//            VOL=SER=&VOL,SPACE=(CYL,(5,2)),\n//            DCB=(DSORG=PS,RECFM=VB,LRECL=260,BLKSIZE=27998)\n./ ADD NAME=J02CSI\n//J02CSI   JOB (ACCT),'SMPE DEFINE CSIS',CLASS=A,MSGCLASS=X,\n//             NOTIFY=&SYSUID,REGION=0M\n//* CHANGE VOLUMES(USER00) TO YOUR VOLUME\n//DEFCSI   EXEC PGM=IDCAMS\n//SYSPRINT DD SYSOUT=*\n//SYSIN    DD *\n DEFINE CLUSTER (NAME(SMPE.PRAC.GLOBAL.CSI) -\n   FREESPACE(10 5) KEYS(24 0) RECORDSIZE(24 143) -\n   SHAREOPTIONS(2 3) VOLUMES(USER00) CYLINDERS(5 5)) -\n   DATA (NAME(SMPE.PRAC.GLOBAL.CSI.DATA) CONTROLINTERVALSIZE(4096)) -\n   INDEX (NAME(SMPE.PRAC.GLOBAL.CSI.INDEX) CONTROLINTERVALSIZE(2048))\n DEFINE CLUSTER (NAME(SMPE.PRAC.MVST.CSI) -\n   FREESPACE(10 5) KEYS(24 0) RECORDSIZE(24 143) -\n   SHAREOPTIONS(2 3) VOLUMES(USER00) CYLINDERS(5 5)) -\n   DATA (NAME(SMPE.PRAC.MVST.CSI.DATA) CONTROLINTERVALSIZE(4096)) -\n   INDEX (NAME(SMPE.PRAC.MVST.CSI.INDEX) CONTROLINTERVALSIZE(2048))\n DEFINE CLUSTER (NAME(SMPE.PRAC.MVSD.CSI) -\n   FREESPACE(10 5) KEYS(24 0) RECORDSIZE(24 143) -\n   SHAREOPTIONS(2 3) VOLUMES(USER00) CYLINDERS(5 5)) -\n   DATA (NAME(SMPE.PRAC.MVSD.CSI.DATA) CONTROLINTERVALSIZE(4096)) -\n   INDEX (NAME(SMPE.PRAC.MVSD.CSI.INDEX) CONTROLINTERVALSIZE(2048))\n/*\n./ ADD NAME=J03ZONES\n//J03ZONES JOB (ACCT),'SMPE DEFINE ZONES',CLASS=A,MSGCLASS=X,\n//             NOTIFY=&SYSUID,REGION=0M\n//         JCLLIB ORDER=SMPE.PRAC.JCL\n//RUN      EXEC SMPEPRC\n//SMPE.SMPCNTL DD *\n SET BDY(GLOBAL) .\n UCLIN .\n   ADD OPTIONS(GOPT) PAGELEN(60) .\n   ADD GLOBALZONE SREL(Z038) OPTIONS(GOPT)\n       ZONEINDEX((MVST,SMPE.PRAC.MVST.CSI,TARGET),\n                 (MVSD,SMPE.PRAC.MVSD.CSI,DLIB)) .\n   ADD DDDEF(SMPPTS) DA(SMPE.PRAC.SMPPTS) SHR .\n   ADD DDDEF(SMPLOG) DA(SMPE.PRAC.SMPLOG) MOD .\n ENDUCL .\n SET BDY(MVST) .\n UCLIN .\n   ADD OPTIONS(TOPT) PAGELEN(60) .\n   ADD TARGETZONE(MVST) SREL(Z038) OPTIONS(TOPT) RELATED(MVSD) .\n   ADD DDDEF(SMPLOGA) DA(SMPE.PRAC.SMPLOGA) MOD .\n   ADD DDDEF(SMPSCDS) DA(SMPE.PRAC.SMPSCDS) SHR .\n   ADD DDDEF(SMPMTS) DA(SMPE.PRAC.SMPMTS) SHR .\n   ADD DDDEF(SMPSTS) DA(SMPE.PRAC.SMPSTS) SHR .\n   ADD DDDEF(SDUMMYL) DA(SMPE.PRAC.SDUMMYL) SHR .\n ENDUCL .\n SET BDY(MVSD) .\n UCLIN .\n   ADD OPTIONS(DOPT) PAGELEN(60) .\n   ADD DLIBZONE(MVSD) SREL(Z038) OPTIONS(DOPT) RELATED(MVST) .\n   ADD DDDEF(SMPLOGA) DA(SMPE.PRAC.SMPLOGA) MOD .\n   ADD DDDEF(ADUMMYL) DA(SMPE.PRAC.ADUMMYL) SHR .\n ENDUCL .\n/*\n./ ADD NAME=J04USRMD\n//J04USRMD JOB (ACCT),'SMPE CREATE USERMODS',CLASS=A,MSGCLASS=X,\n//             NOTIFY=&SYSUID,REGION=0M\n//* CREATES TWO SEQUENTIAL DATASETS HOLDING THE DUMMY USERMODS\n//         SET VOL=USER00\n//ALLOC    EXEC PGM=IEFBR14\n//U1       DD DSN=SMPE.PRAC.USR0001,DISP=(NEW,CATLG),UNIT=SYSALLDA,\n//            VOL=SER=&VOL,SPACE=(TRK,(1,1)),\n//            DCB=(RECFM=FB,LRECL=80,BLKSIZE=27920)\n//U2       DD DSN=SMPE.PRAC.USR0002,DISP=(NEW,CATLG),UNIT=SYSALLDA,\n//            VOL=SER=&VOL,SPACE=(TRK,(1,1)),\n//            DCB=(RECFM=FB,LRECL=80,BLKSIZE=27920)\n//GEN1     EXEC PGM=IEBGENER\n//SYSPRINT DD SYSOUT=*\n//SYSIN    DD DUMMY\n//SYSUT2   DD DSN=SMPE.PRAC.USR0001,DISP=OLD\n//SYSUT1   DD DATA,DLM=@@\n++USERMOD(USR0001) .\n++VER(Z038) .\n++SAMP(DUMMYJ1) DISTLIB(ADUMMYL) SYSLIB(SDUMMYL) .\n//DUMMYJ1  JOB (ACCT),'DUMMY SMPE',CLASS=A,MSGCLASS=X\n//* SAMPLE ADDED BY DUMMY USERMOD USR0001 - DOES NOTHING\n//STEP1    EXEC PGM=IEFBR14\n@@\n//GEN2     EXEC PGM=IEBGENER\n//SYSPRINT DD SYSOUT=*\n//SYSIN    DD DUMMY\n//SYSUT2   DD DSN=SMPE.PRAC.USR0002,DISP=OLD\n//SYSUT1   DD DATA,DLM=@@\n++USERMOD(USR0002) .\n++VER(Z038) PRE(USR0001) .\n++SAMP(DUMMYJ2) DISTLIB(ADUMMYL) SYSLIB(SDUMMYL) .\n//DUMMYJ2  JOB (ACCT),'DUMMY SMPE',CLASS=A,MSGCLASS=X\n//* SAMPLE ADDED BY DUMMY USERMOD USR0002 - DOES NOTHING\n//STEP1    EXEC PGM=IEFBR14\n@@\n./ ADD NAME=J05RECV1\n//J05RECV1 JOB (ACCT),'SMPE RECEIVE USR0001',CLASS=A,MSGCLASS=X,\n//             NOTIFY=&SYSUID,REGION=0M\n//         JCLLIB ORDER=SMPE.PRAC.JCL\n//RUN      EXEC SMPEPRC\n//SMPE.SMPPTFIN DD DISP=SHR,DSN=SMPE.PRAC.USR0001\n//SMPE.SMPCNTL DD *\n SET BDY(GLOBAL) .\n RECEIVE S(USR0001) .\n/*\n./ ADD NAME=J06RECV2\n//J06RECV2 JOB (ACCT),'SMPE RECEIVE USR0002',CLASS=A,MSGCLASS=X,\n//             NOTIFY=&SYSUID,REGION=0M\n//         JCLLIB ORDER=SMPE.PRAC.JCL\n//RUN      EXEC SMPEPRC\n//SMPE.SMPPTFIN DD DISP=SHR,DSN=SMPE.PRAC.USR0002\n//SMPE.SMPCNTL DD *\n SET BDY(GLOBAL) .\n RECEIVE S(USR0002) .\n/*\n./ ADD NAME=J07LIST\n//J07LIST  JOB (ACCT),'SMPE LIST ZONES',CLASS=A,MSGCLASS=X,\n//             NOTIFY=&SYSUID,REGION=0M\n//         JCLLIB ORDER=SMPE.PRAC.JCL\n//RUN      EXEC SMPEPRC\n//SMPE.SMPCNTL DD *\n SET BDY(GLOBAL) .\n LIST SYSMODS .\n LIST DDDEF .\n SET BDY(MVST) .\n LIST SYSMODS .\n SET BDY(MVSD) .\n LIST SYSMODS .\n/*\n./ ADD NAME=J08PRECK\n//J08PRECK JOB (ACCT),'SMPE PREREQ TEST',CLASS=A,MSGCLASS=X,\n//             NOTIFY=&SYSUID,REGION=0M\n//         JCLLIB ORDER=SMPE.PRAC.JCL\n//* EXPECT A NON-ZERO RC: USR0002 NEEDS USR0001 (PRE)\n//RUN      EXEC SMPEPRC\n//SMPE.SMPCNTL DD *\n SET BDY(MVST) .\n APPLY S(USR0002) CHECK .\n/*\n./ ADD NAME=J09APCK1\n//J09APCK1 JOB (ACCT),'SMPE APPLY CHECK 1',CLASS=A,MSGCLASS=X,\n//             NOTIFY=&SYSUID,REGION=0M\n//         JCLLIB ORDER=SMPE.PRAC.JCL\n//RUN      EXEC SMPEPRC\n//SMPE.SMPCNTL DD *\n SET BDY(MVST) .\n APPLY S(USR0001) CHECK .\n/*\n./ ADD NAME=J10APPLY1\n//J10APPLY1 JOB (ACCT),'SMPE APPLY USR0001',CLASS=A,MSGCLASS=X,\n//             NOTIFY=&SYSUID,REGION=0M\n//         JCLLIB ORDER=SMPE.PRAC.JCL\n//RUN      EXEC SMPEPRC\n//SMPE.SMPCNTL DD *\n SET BDY(MVST) .\n APPLY S(USR0001) .\n/*\n./ ADD NAME=J11APPLY2\n//J11APPLY2 JOB (ACCT),'SMPE APPLY USR0002',CLASS=A,MSGCLASS=X,\n//             NOTIFY=&SYSUID,REGION=0M\n//         JCLLIB ORDER=SMPE.PRAC.JCL\n//RUN      EXEC SMPEPRC\n//SMPE.SMPCNTL DD *\n SET BDY(MVST) .\n APPLY S(USR0002) .\n/*\n./ ADD NAME=J12RESTR\n//J12RESTR JOB (ACCT),'SMPE RESTORE USR0002',CLASS=A,MSGCLASS=X,\n//             NOTIFY=&SYSUID,REGION=0M\n//         JCLLIB ORDER=SMPE.PRAC.JCL\n//* BACK USR0002 OUT OF THE TARGET LIBRARY (NOT ALLOWED AFTER ACCEPT)\n//RUN      EXEC SMPEPRC\n//SMPE.SMPCNTL DD *\n SET BDY(MVST) .\n RESTORE S(USR0002) .\n/*\n./ ADD NAME=J13REJCT\n//J13REJCT JOB (ACCT),'SMPE REJECT USR0002',CLASS=A,MSGCLASS=X,\n//             NOTIFY=&SYSUID,REGION=0M\n//         JCLLIB ORDER=SMPE.PRAC.JCL\n//* REMOVE USR0002 FROM THE GLOBAL ZONE / SMPPTS\n//RUN      EXEC SMPEPRC\n//SMPE.SMPCNTL DD *\n SET BDY(GLOBAL) .\n REJECT S(USR0002) .\n/*\n./ ADD NAME=J14ACCK1\n//J14ACCK1 JOB (ACCT),'SMPE ACCEPT CHECK',CLASS=A,MSGCLASS=X,\n//             NOTIFY=&SYSUID,REGION=0M\n//         JCLLIB ORDER=SMPE.PRAC.JCL\n//RUN      EXEC SMPEPRC\n//SMPE.SMPCNTL DD *\n SET BDY(MVSD) .\n ACCEPT S(USR0001) CHECK .\n/*\n./ ADD NAME=J15ACPT1\n//J15ACPT1 JOB (ACCT),'SMPE ACCEPT USR0001',CLASS=A,MSGCLASS=X,\n//             NOTIFY=&SYSUID,REGION=0M\n//         JCLLIB ORDER=SMPE.PRAC.JCL\n//RUN      EXEC SMPEPRC\n//SMPE.SMPCNTL DD *\n SET BDY(MVSD) .\n ACCEPT S(USR0001) .\n/*\n./ ADD NAME=J16REPRT\n//J16REPRT JOB (ACCT),'SMPE REPORTS',CLASS=A,MSGCLASS=X,\n//             NOTIFY=&SYSUID,REGION=0M\n//         JCLLIB ORDER=SMPE.PRAC.JCL\n//RUN      EXEC SMPEPRC\n//SMPE.SMPCNTL DD *\n SET BDY(MVST) .\n REPORT ERRSYSMODS .\n REPORT SYSMODS .\n LIST SYSMODS .\n/*\n./ ADD NAME=J17UCLIN\n//J17UCLIN JOB (ACCT),'SMPE UCLIN PRACTICE',CLASS=A,MSGCLASS=X,\n//             NOTIFY=&SYSUID,REGION=0M\n//         JCLLIB ORDER=SMPE.PRAC.JCL\n//RUN      EXEC SMPEPRC\n//SMPE.SMPCNTL DD *\n SET BDY(MVST) .\n UCLIN .\n   ADD DDDEF(SMPTLIB) DA(SMPE.PRAC.SMPTLIB) SHR .\n ENDUCL .\n LIST DDDEF .\n UCLIN .\n   DEL DDDEF(SMPTLIB) .\n ENDUCL .\n LIST DDDEF .\n/*\n./ ADD NAME=J18CLEAN\n//J18CLEAN JOB (ACCT),'SMPE CLEANUP',CLASS=A,MSGCLASS=X,\n//             NOTIFY=&SYSUID,REGION=0M\n//* DELETES THE WHOLE SANDBOX SO YOU CAN START AGAIN\n//DEL      EXEC PGM=IDCAMS\n//SYSPRINT DD SYSOUT=*\n//SYSIN    DD *\n DELETE SMPE.PRAC.GLOBAL.CSI CLUSTER PURGE\n DELETE SMPE.PRAC.MVST.CSI CLUSTER PURGE\n DELETE SMPE.PRAC.MVSD.CSI CLUSTER PURGE\n DELETE SMPE.PRAC.SMPPTS PURGE\n DELETE SMPE.PRAC.SMPSCDS PURGE\n DELETE SMPE.PRAC.SMPMTS PURGE\n DELETE SMPE.PRAC.SMPSTS PURGE\n DELETE SMPE.PRAC.SDUMMYL PURGE\n DELETE SMPE.PRAC.ADUMMYL PURGE\n DELETE SMPE.PRAC.SMPLOG PURGE\n DELETE SMPE.PRAC.SMPLOGA PURGE\n DELETE SMPE.PRAC.USR0001 PURGE\n DELETE SMPE.PRAC.USR0002 PURGE\n SET MAXCC=0\n/*\n##\n"
